ng":{"label":"Stenläggning & plattläggning"},"annat":{"label":"Annat"}}},"contactHint":"Det räcker med telefon eller e-post.","errors":{"name":"Ange ditt namn.","contact":"Ange telefonnummer eller e-postadress, så att vi kan nå dig.","phone":"Ange ett giltigt telefonnummer.","email":"Ange en giltig e-postadress.","workType":"Välj typ av arbete."},"submit":"Skicka förfrågan","sending":"Skickar…","sendFailed":"Förfrågan kunde inte skickas. Försök igen eller ring oss på","closeHint":"Du kan stänga rutan när som helst genom att klicka utanför eller på","closeHintButton":"X","confirmation":"Tack! Vi återkommer strax","emailSubject":"Offertförfrågan från {namn}"},"ui":{"skipLink":"Hoppa till innehållet","openMenu":"Öppna meny","closeMenu":"Stäng meny","menuLabel":"Meny","mainMenuLabel":"Huvudmeny","quickLinksLabel":"Snabblänkar","callPrefix":"Ring","homeLinkLabel":"Markmontage BEAB AB – startsida","breadcrumbsLabel":"Brödsmulor","breadcrumbHome":"Hem","carouselPrevious":"Föregående uppdrag","carouselNext":"Nästa uppdrag","carouselGoTo":"Gå till position {n} av {total}","uppdragFilterLabel":"Filtrera uppdrag","stepPrefix":"Steg","mapTitlePrefix":"Karta:","closeLabel":"Stäng","ratingLabel":"{n} av 5 stjärnor","cookieText":"Vi vill använda kakor för att se hur besökare använder sidan, så att vi kan göra den bättre. Godkänner du det?","cookieAccept":"Godkänn","cookieDecline":"Nej tack","cookieSettings":"Kakinställningar"},"servicePage":{"badge":"Tjänst","cta":{"heading":"Har du ett markprojekt på gång?","text":"Kontakta oss för ett kostnadsfritt hembesök, så går vi igenom förutsättningarna tillsammans.","button":{"label":"Begär offert","href":"#offert"}},"factsTitle":"Fakta om tjänsten","factLabels":{"service":"Tjänst","performedBy":"Utförs av","seat":"Säte","area":"Område","org":"Org.nr"},"contactTagline":"Mark- och grundarbeten sedan 2002","contactButton":{"label":"Begär offert","href":"#offert"},"backLink":{"label":"Tillbaka till tjänster","href":"/#tjanster"},"moreHeading":"Fler tjänster","breadcrumbLabel":"Tjänster","breadcrumbHref":"/#tjanster"},"notFound":{"eyebrow":"Fel 404","heading":"Sidan hittades inte","text":"Sidan du letar efter finns inte längre, eller så har adressen ändrats.","button":{"label":"Till startsidan","href":"/"},"seoTitle":"Sidan hittades inte"},"services":{"order":["schaktning-markarbeten","dranering","grundlaggning","va-arbeten","fiber","anlaggning-vagar-planer","stenlaggning","pooler","transporter-kranbil","totalentreprenad"],"items":{"schaktning-markarbeten":{"slug":"schaktning-markarbeten","name":"Schaktning & markarbeten","shortDescription":"Schaktning och markarbeten som förbereder tomten inför bygget, anpassade efter markförhållandena.","description":["Ett bygge börjar alltid under mark, och ett väl förberett underlag avgör hur resten av projektet går. Markmontage BEAB AB utför schaktning och markarbeten i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd, både som en del av större entreprenader och som fristående uppdrag.","Vi hanterar schaktning för grund, ledningar och anslutningar, samt terrassering och iordningställande av tomtmark inför fortsatt byggnation. Varje uppdrag anpassas efter markförhållandena på plats, från lera och berg till mer lättarbetad mark.","Som totalentreprenör kan vi samordna schaktningen med efterföljande moment som grundläggning och VA-arbeten, så att projektet flyter på utan onödiga avbrott mellan olika entreprenörer.","Kontakta oss för en kostnadsfri offert, så tittar vi tillsammans på förutsättningarna för just din tomt."],"icon":"Shovel","image":{"src":"/photos/markmontage-minigravare.webp","variants":[{"width":480,"src":"/photos/markmontage-minigravare-480.webp"},{"width":800,"src":"/photos/markmontage-minigravare-800.webp"},{"width":1200,"src":"/photos/markmontage-minigravare-1200.webp"},{"width":1600,"src":"/photos/markmontage-minigravare-1600.webp"},{"width":2400,"src":"/photos/markmontage-minigravare.webp"}],"alt":"Gul minigrävare vid markarbete i en trädgård"},"seo":{"title":"Schaktning & markarbeten i Kungälv","description":"Schaktning och markarbeten som förbereder tomten inför bygget, anpassade efter markförhållandena."}},"dranering":{"slug":"dranering","name":"Dränering","shortDescription":"Dränering som skyddar grunden mot fukt och sättningsskador, utförd enligt branschens riktlinjer.","description":["Bristfällig dränering är en av de vanligaste orsakerna till fukt- och sättningsskador i äldre hus. Markmontage BEAB AB utför dränering i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd, både vid nybyggnation och som åtgärd vid befintliga fuktproblem.","Arbetet omfattar schaktning runt grunden, ny dränering och fuktskydd, samt återfyllning och iordningställande av marken efteråt. Vi lägger stor vikt vid att dräneringen leder bort vatten på rätt sätt, anpassat efter husets grundläggning och markens lutning.","Dränering vid en befintlig bostad ger i många fall rätt till rotavdrag på arbetskostnaden. Avdraget är 30 procent av arbetskostnaden, högst 50 000 kronor per person och år. Exempel: kostar arbetet 80 000 kronor blir rotavdraget 24 000 kronor, och du betalar 56 000 kronor för arbetet. Material och maskiner ger inget avdrag. Äger ni huset tillsammans kan ni dela på avdraget. Vi drar av beloppet direkt på fakturan och sköter ansökan till Skatteverket.","Kontakta oss för ett kostnadsfritt hembesök, så gör vi en bedömning av dräneringen vid din fastighet."],"icon":"Droplets","image":{"src":"/photos/markmontage-dranering-ror.webp","variants":[{"width":480,"src":"/photos/markmontage-dranering-ror-480.webp"},{"width":800,"src":"/photos/markmontage-dranering-ror-800.webp"},{"width":1200,"src":"/photos/markmontage-dranering-ror-1200.webp"},{"width":1600,"src":"/photos/markmontage-dranering-ror-1600.webp"},{"width":1800,"src":"/photos/markmontage-dranering-ror.webp"}],"alt":"Orange dräneringsrör med grenrör i en öppen schakt"},"seo":{"title":"Dränering i Kungälv","description":"Dränering som skyddar grunden mot fukt och sättningsskador, utförd enligt branschens riktlinjer."}},"grundlaggning":{"slug":"grundlaggning","name":"Grundläggning","shortDescription":"Grundläggning för nybyggnation och tillbyggnad, anpassad efter markens bärighet.","description":["Grunden bär hela byggnaden, och felaktigt utförd grundläggning är svår och kostsam att åtgärda i efterhand. Markmontage BEAB AB utför grundläggning i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd, vid såväl nybyggnation som tillbyggnad.","Vi utför bland annat gjutning av platta på mark, grundsulor och källargrunder, alltid anpassat efter markens bärighet och grundvattenförhållandena på platsen. Markisolering och fuktskydd ingår som en naturlig del av arbetet.","Tack vare vår erfarenhet av mark- och grundarbeten vet vi vad som krävs för en grund som håller över tid. Vid behov samordnar vi arbetet med övriga entreprenörer i projektet.","Hör av dig för en kostnadsfri offert, så berättar vi mer om vad som gäller för grundläggningen på just din tomt."],"icon":"Layers","image":{"src":"/photos/markmontage-stalstomme.webp","variants":[{"width":480,"src":"/photos/markmontage-stalstomme-480.webp"},{"width":800,"src":"/photos/markmontage-stalstomme-800.webp"},{"width":1200,"src":"/photos/markmontage-stalstomme-1200.webp"},{"width":1600,"src":"/photos/markmontage-stalstomme-1600.webp"},{"width":2250,"src":"/photos/markmontage-stalstomme.webp"}],"alt":"Kranbil och medarbetare vid ett vägarbete"},"seo":{"title":"Grundläggning i Kungälv","description":"Grundläggning för nybyggnation och tillbyggnad, anpassad efter markens bärighet."}},"va-arbeten":{"slug":"va-arbeten","name":"VA-arbeten","shortDescription":"Vatten- och avloppsarbeten – ledningar på den egna tomten och anslutning till det kommunala nätet.","description":["Vatten- och avloppsarbeten kräver både rätt kompetens och rätt tillstånd, eftersom felaktigt utförda VA-installationer kan bli kostsamma att åtgärda. Markmontage BEAB AB utför VA-arbeten i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd.","Vi lägger och byter ledningar för vatten, spillvatten och dagvatten, samt utför anslutningar till kommunalt VA-nät eller enskilda avloppsanläggningar. Arbetet utförs enligt gällande branschregler för VA-installationer.","Som totalentreprenör kan vi samordna VA-arbetet med schaktning och återställning av marken, så att du slipper hålla ihop flera separata entreprenörer.","Kontakta oss för en kostnadsfri offert på VA-arbetet vid din fastighet."],"icon":"Waves","image":{"src":"/photos/markmontage-gravmaskin-ror.webp","variants":[{"width":480,"src":"/photos/markmontage-gravmaskin-ror-480.webp"},{"width":800,"src":"/photos/markmontage-gravmaskin-ror-800.webp"},{"width":1200,"src":"/photos/markmontage-gravmaskin-ror-1200.webp"},{"width":1600,"src":"/photos/markmontage-gravmaskin-ror-1600.webp"},{"width":2400,"src":"/photos/markmontage-gravmaskin-ror-2400.webp"},{"width":3840,"src":"/photos/markmontage-gravmaskin-ror.webp"}],"alt":"Grävmaskin och medarbetare i varselkläder vid en schakt"},"seo":{"title":"VA-arbeten i Kungälv","description":"Vatten- och avloppsarbeten – ledningar på den egna tomten och anslutning till det kommunala nätet."}},"anlaggning-vagar-planer":{"slug":"anlaggning-vagar-planer","name":"Anläggning av vägar & planer","shortDescription":"Anläggning av vägar, uppfarter och asfalterade eller grusade ytor med hållbar bärighet.","description":["En väl anlagd väg eller uppställningsyta kräver rätt uppbyggnad i flera lager för att hålla över tid, oavsett belastning och väderlek. Markmontage BEAB AB utför anläggning av vägar och planer i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd.","Vi anlägger uppfarter, parkeringsytor och interna vägar, med förstärkningslager anpassade efter markens bärighet och den tänkta belastningen. Ytorna kan färdigställas med allt från grus till asfalt beroende på behov.","Rätt dränering och lutning i uppbyggnaden är avgörande för att undvika vattenansamling och tjälskador, något vi planerar för redan i markarbetet.","Hör av dig för en kostnadsfri offert, så går vi igenom vad som passar bäst för just din yta."],"icon":"Route","image":{"src":"/photos/markmontage-vagarbete-avstangning.webp","variants":[{"width":480,"src":"/photos/markmontage-vagarbete-avstangning-480.webp"},{"width":800,"src":"/photos/markmontage-vagarbete-avstangning-800.webp"},{"width":1200,"src":"/photos/markmontage-vagarbete-avstangning-1200.webp"},{"width":1600,"src":"/photos/markmontage-vagarbete-avstangning-1600.webp"},{"width":1799,"src":"/photos/markmontage-vagarbete-avstangning.webp"}],"alt":"Avspärrat vägarbete längs en gata"},"seo":{"title":"Anläggning av vägar & planer i Kungälv","description":"Anläggning av vägar, uppfarter och asfalterade eller grusade ytor med hållbar bärighet."}},"stenlaggning":{"slug":"stenlaggning","name":"Stenläggning & plattläggning","shortDescription":"Stenläggning och plattläggning utomhus med stabilt underlag för gångar, uteplatser och infarter.","description":["En hållbar stenläggning avgörs av underarbetet minst lika mycket som av själva stenen eller plattan. Markmontage BEAB AB utför stenläggning och plattläggning utomhus i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd.","Vi bygger upp bärlager och sättsand enligt branschens riktlinjer inför läggning av marksten, plattor eller kantsten till gångar, uteplatser och infarter, så att ytan ligger stabilt och jämnt även efter flera års användning.","Vid behov kombinerar vi stenläggningen med dränering under ytan för att leda bort vatten och minska risken för sättningar och ogräs i fogarna.","Kontakta oss för en kostnadsfri offert på stenläggningen vid din fastighet."],"icon":"LayoutGrid","image":{"src":"/photos/markmontage-stenlaggning-pagar.webp","variants":[{"width":480,"src":"/photos/markmontage-stenlaggning-pagar-480.webp"},{"width":800,"src":"/photos/markmontage-stenlaggning-pagar-800.webp"},{"width":1200,"src":"/photos/markmontage-stenlaggning-pagar-1200.webp"},{"width":1600,"src":"/photos/markmontage-stenlaggning-pagar-1600.webp"},{"width":1799,"src":"/photos/markmontage-stenlaggning-pagar.webp"}],"alt":"Marksten läggs på en gårdsplan framför ett hus"},"seo":{"title":"Stenläggning & plattläggning i Kungälv","description":"Stenläggning och plattläggning utomhus med stabilt underlag för gångar, uteplatser och infarter."}},"totalentreprenad":{"slug":"totalentreprenad","name":"Totalentreprenad","shortDescription":"Totalentreprenad där vi tar helhetsansvar för mark- och grundarbetet från start till avslut.","description":["På större projekt är det ofta en fördel att samla mark- och grundarbetet hos en och samma entreprenör. Markmontage BEAB AB åtar sig totalentreprenader inom mark- och grundarbeten i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd.","Som totalentreprenör tar vi helhetsansvaret för projektet – från schaktning och dränering till grundläggning, VA-arbeten och färdigställande av mark – och samordnar de moment som krävs för att arbetet ska flyta på utan onödiga förseningar.","Du får en kontaktperson genom hela projektet och en tydlig tidsplan, istället för att själv behöva samordna flera olika entreprenörer.","Kontakta oss för en kostnadsfri offert, så berättar vi mer om hur en totalentreprenad kan se ut för just ditt projekt."],"icon":"HardHat","image":{"src":"/photos/markmontage-vagarbete.webp","variants":[{"width":480,"src":"/photos/markmontage-vagarbete-480.webp"},{"width":800,"src":"/photos/markmontage-vagarbete-800.webp"},{"width":1200,"src":"/photos/markmontage-vagarbete-1200.webp"},{"width":1600,"src":"/photos/markmontage-vagarbete-1600.webp"},{"width":2340,"src":"/photos/markmontage-vagarbete.webp"}],"alt":"Vägarbete med avspärrning, grävmaskin på släp och kranbil","focus":"28% 50%"},"seo":{"title":"Totalentreprenad i Kungälv","description":"Totalentreprenad där vi tar helhetsansvar för mark- och grundarbetet från start till avslut."}},"fiber":{"slug":"fiber","name":"Fiberblåsning & fiberinstallation","shortDescription":"Fiberblåsning och fiberinstallation – från schakt och rör i marken till inblåst fiberkabel, även över vatten.","description":["Markmontage BEAB AB utför fiberblåsning och fiberinstallation i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd. Vi tar hand om arbetet i marken: schakt, förläggning av rör och kanalisation och inblåsning av fiberkabeln.","Vid fiberblåsning blåses kabeln in i ett tomrör med hjälp av tryckluft. Metoden är skonsam mot kabeln och gör det möjligt att dra långa sträckor i ett stycke.","Vi har också utrustning för att förlägga kabel över vatten, där kabeln läggs ut från pråm med hjälp av båt.","Kontakta oss så berättar vi mer om hur vi kan hjälpa till i ditt fiberprojekt."],"icon":"Cable","image":{"src":"/photos/markmontage-fiber-bat.webp","variants":[{"width":480,"src":"/photos/markmontage-fiber-bat-480.webp"},{"width":800,"src":"/photos/markmontage-fiber-bat-800.webp"},{"width":1125,"src":"/photos/markmontage-fiber-bat.webp"}],"alt":"Båt bogserar pråmen med kabeltrumman vid kabelförläggning i sjö","focus":"50% 45%"},"seo":{"title":"Fiberblåsning och fiberinstallation i Kungälv","description":"Fiberblåsning och fiberinstallation i Kungälv, Stenungsund, Ale, Trestad och Göteborg – schakt, rör och inblåsning av fiberkabel."}},"transporter-kranbil":{"slug":"transporter-kranbil","name":"Transporter & kranbil","shortDescription":"Transporter och lyft med egna kranlastbilar – maskiner, betongelement, material och mycket annat.","description":["Markmontage BEAB AB har egna kranlastbilar och utför transporter och kranlyft i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd. Med kranen på bilen kan vi både frakta och lyfta på plats.","Vi transporterar bland annat grävmaskiner, betongelement, pooler, växthus och byggmaterial, och lyfter det dit det ska. Med arbetskorg på kranen utför vi också arbeten på höjd, till exempel vid stolpar och ledningar.","Hör av dig med vad som ska fraktas eller lyftas, så återkommer vi med ett förslag."],"icon":"Truck","image":{"src":"/photos/markmontage-fordonsparken.webp","variants":[{"width":480,"src":"/photos/markmontage-fordonsparken-480.webp"},{"width":800,"src":"/photos/markmontage-fordonsparken-800.webp"},{"width":1200,"src":"/photos/markmontage-fordonsparken-1200.webp"},{"width":1600,"src":"/photos/markmontage-fordonsparken-1600.webp"},{"width":2016,"src":"/photos/markmontage-fordonsparken.webp"}],"alt":"Markmontages lastbilar och kranbilar på rad","focus":"50% 55%"},"seo":{"title":"Transporter och kranbil i Kungälv","description":"Transporter och kranlyft med egna kranlastbilar i Kungälv, Stenungsund, Ale, Trestad och Göteborg."}},"pooler":{"slug":"pooler","name":"Pooler","shortDescription":"Schakt, grund och montering av pooler – både glasfiberpooler och gjutna betongpooler.","description":["Markmontage BEAB AB bygger pooler i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd. Vi tar hand om allt arbete i marken, från schakt till färdig pool.","För en glasfiberpool schaktar vi gropen, lägger en bädd av makadam, lyfter poolen på plats med kran och kopplar in rören. För en betongpool lägger vi isolering, gjuter bottenplattan, bygger väggarna av formblock och gjuter dem.","Med egna kranbilar kan vi både frakta poolen och lyfta den på plats, även där det är trångt.","Kontakta oss för ett kostnadsfritt hembesök, så går vi igenom förutsättningarna på din tomt."],"icon":"Waves","image":{"src":"/photos/markmontage-pool-glasfiber.webp","variants":[{"width":480,"src":"/photos/markmontage-pool-glasfiber-480.webp"},{"width":800,"src":"/photos/markmontage-pool-glasfiber-800.webp"},{"width":1200,"src":"/photos/markmontage-pool-glasfiber-1200.webp"},{"width":1600,"src":"/photos/markmontage-pool-glasfiber-1600.webp"},{"width":1800,"src":"/photos/markmontage-pool-glasfiber.webp"}],"alt":"En glasfiberpool på plats i en schaktad grop i en trädgård","focus":"50% 45%"},"seo":{"title":"Pooler i Kungälv","description":"Schakt, grund och montering av glasfiberpooler och betongpooler i Kungälv, Stenungsund, Ale, Trestad och Göteborg."}}}},"uppdrag":{"order":["schakt","pool","betongpool","grund","dagvatten","vagar","marksten","helhet","fiber-sjo","kranlyft","maskintransport","bod"],"items":{"schakt":{"tag":"Markarbeten","title":"Schakt och massförflyttning","href":"/tjanster/schaktning-markarbeten","image":{"src":"/photos/markmontage-minigravare-grasmatta.webp","variants":[{"width":480,"src":"/photos/markmontage-minigravare-grasmatta-480.webp"},{"width":800,"src":"/photos/markmontage-minigravare-grasmatta-800.webp"},{"width":1200,"src":"/photos/markmontage-minigravare-grasmatta-1200.webp"},{"width":1600,"src":"/photos/markmontage-minigravare-grasmatta-1600.webp"},{"width":1800,"src":"/photos/markmontage-minigravare-grasmatta.webp"}],"alt":"Minigrävare som schaktar i en gräsmatta"}},"grund":{"tag":"Grund & dränering","title":"Platta på mark och grundsulor","href":"/tjanster/grundlaggning","image":{"src":"/photos/markmontage-geotextil.webp","variants":[{"width":480,"src":"/photos/markmontage-geotextil-480.webp"},{"width":800,"src":"/photos/markmontage-geotextil-800.webp"},{"width":1200,"src":"/photos/markmontage-geotextil-1200.webp"},{"width":1600,"src":"/photos/markmontage-geotextil-1600.webp"},{"width":1799,"src":"/photos/markmontage-geotextil.webp"}],"alt":"Markduk utlagd på en avschaktad yta innan bärlagret läggs"}},"dagvatten":{"tag":"Grund & dränering","title":"Dagvatten och fuktskydd","href":"/tjanster/dranering","image":{"src":"/photos/markmontage-dagvatten-ror.webp","variants":[{"width":480,"src":"/photos/markmontage-dagvatten-ror-480.webp"},{"width":800,"src":"/photos/markmontage-dagvatten-ror-800.webp"},{"width":1200,"src":"/photos/markmontage-dagvatten-ror-1200.webp"},{"width":1600,"src":"/photos/markmontage-dagvatten-ror-1600.webp"},{"width":1800,"src":"/photos/markmontage-dagvatten-ror.webp"}],"alt":"Orange dagvattenrör med rördelar i en schakt"}},"vagar":{"tag":"Markarbeten","title":"Vägar, planer oc