webp"}],"alt":"Kranlastbil med en grävmaskin på flaket"}},"bod":{"tag":"Transporter","title":"Lyft av byggbod","href":"/tjanster/transporter-kranbil","image":{"src":"/photos/markmontage-kranbil-bod.webp","variants":[{"width":480,"src":"/photos/markmontage-kranbil-bod-480.webp"},{"width":800,"src":"/photos/markmontage-kranbil-bod-800.webp"},{"width":1200,"src":"/photos/markmontage-kranbil-bod-1200.webp"},{"width":1242,"src":"/photos/markmontage-kranbil-bod.webp"}],"alt":"Kranbil lyfter en blå byggbod","focus":"40% 45%"}}}},"certificates":{"order":["iso-9001","iso-14001","iso-45001","aa-kreditvardighet"],"items":{"iso-9001":{"name":"ISO 9001 – Kvalitet","issuer":"Svensk Certifiering","description":"Den internationella standarden för kvalitetsledning. Vi har ett ledningssystem för hur vi planerar, genomför och följer upp våra uppdrag, och vi arbetar hela tiden med att bli bättre. För dig som beställare betyder det tydliga rutiner från offert till färdigt jobb.","validUntil":"9 februari 2028","document":"/dokument/markmontage-iso-9001.pdf","image":{"src":"/photos/certifikat-iso9001.webp","variants":[{"width":240,"src":"/photos/certifikat-iso9001-240.webp"},{"width":480,"src":"/photos/certifikat-iso9001.webp"}],"alt":"Märket Certifierat ISO 9001 från Svensk Certifiering"}},"iso-14001":{"name":"ISO 14001 – Miljö","issuer":"Svensk Certifiering","description":"Den internationella standarden för miljöledning. Vi kartlägger hur vårt arbete påverkar miljön, till exempel genom maskiner, transporter och massor, och arbetar med mål och åtgärder för att minska påverkan.","validUntil":"9 februari 2028","document":"/dokument/markmontage-iso-14001.pdf","image":{"src":"/photos/certifikat-iso14001.webp","variants":[{"width":240,"src":"/photos/certifikat-iso14001-240.webp"},{"width":480,"src":"/photos/certifikat-iso14001.webp"}],"alt":"Märket Certifierat ISO 14001 från Svensk Certifiering"}},"iso-45001":{"name":"ISO 45001 – Arbetsmiljö","issuer":"Svensk Certifiering","description":"Den internationella standarden för arbetsmiljö. Vi arbetar förebyggande med risker och säkerhet, så att alla som jobbar på eller passerar våra arbetsplatser ska kunna känna sig trygga.","validUntil":"11 december 2027","document":"/dokument/markmontage-iso-45001.pdf","image":{"src":"/photos/certifikat-iso45001.webp","variants":[{"width":240,"src":"/photos/certifikat-iso45001-240.webp"},{"width":480,"src":"/photos/certifikat-iso45001.webp"}],"alt":"Märket Certifierat ISO 45001 från Svensk Certifiering"}},"aa-kreditvardighet":{"name":"AA – God kreditvärdighet","issuer":"Dun & Bradstreet","description":"Markmontage har kreditbetyget AA, God kreditvärdighet, enligt Dun & Bradstreets bedömning i februari 2025. Betyget bygger på företagets ekonomi och betalningsförmåga och visar att vi är en stabil partner att anlita.","validUntil":"","document":"","image":{"src":"/photos/certifikat-aa.webp","variants":[{"width":320,"src":"/photos/certifikat-aa-320.webp"},{"width":640,"src":"/photos/certifikat-aa.webp"}],"alt":"Dun & Bradstreets märke för kreditbetyget AA, God kreditvärdighet, för Markmontage Beab AB"}}}},"pages":{"order":["hem","om-oss","projekt","hallbarhet"],"items":{"hem":{"slug":"","title":"Hem","seo":{"title":"Markarbeten i Kungälv & Göteborg | Markmontage BEAB AB","description":"Markmontage BEAB AB utför mark- och grundarbeten i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd."},"sections":{"order":["hero","certifikat","tjanster","uppdrag","siffror","grund","erbjudanden","om-oss","process","kundomdomen","omdomen","faq","kontakt","karta"],"items":{"hero":{"type":"hero","hidden":false,"anchor":"","label":"","eyebrow":"Markmontage BEAB AB · Sedan 2002","heading":"Mark- och grundarbeten i Kungälv & Göteborg","image":{"src":"/photos/markmontage-gravmaskin-ror.webp","variants":[{"width":480,"src":"/photos/markmontage-gravmaskin-ror-480.webp"},{"width":800,"src":"/photos/markmontage-gravmaskin-ror-800.webp"},{"width":1200,"src":"/photos/markmontage-gravmaskin-ror-12