anpassat"],"items":{"tydligt":{"heading":"Tydligt från start","text":"Vid ett kostnadsfritt hembesök går vi igenom förutsättningarna på plats. Därefter får du en fast offert, så att du vet vad som ingår innan något arbete påbörjas.","icon":"Home","link":{"label":"Så går det till","href":"#process"},"image":{"src":"/photos/markmontage-arbete.webp","variants":[{"width":480,"src":"/photos/markmontage-arbete-480.webp"},{"width":800,"src":"/photos/markmontage-arbete-800.webp"},{"width":1200,"src":"/photos/markmontage-arbete-1200.webp"},{"width":1600,"src":"/photos/markmontage-arbete-1600.webp"},{"width":2400,"src":"/photos/markmontage-arbete.webp"}],"alt":"Medarbetare vid avspärrningen på en arbetsplats med servicebilar","focus":"20% 45%"}},"anpassat":{"heading":"Anpassat efter marken","text":"Varje uppdrag anpassas efter förhållandena på platsen – från lera och berg till mer lättarbetad mark – och efter markens bärighet och grundvattennivå.","icon":"Layers","link":{"label":"Se våra tjänster","href":"#tjanster"},"image":{"src":"/photos/markmontage-minigravare.webp","variants":[{"width":480,"src":"/photos/markmontage-minigravare-480.webp"},{"width":800,"src":"/photos/markmontage-minigravare-800.webp"},{"width":1200,"src":"/photos/markmontage-minigravare-1200.webp"},{"width":1600,"src":"/photos/markmontage-minigravare-1600.webp"},{"width":2400,"src":"/photos/markmontage-minigravare.webp"}],"alt":"Gul minigrävare vid markarbete i en trädgård","focus":"88% 70%"}}}}},"erbjudanden":{"type":"promo","hidden":false,"anchor":"","label":"","boxes":{"order":["totalentreprenad","bygga"],"items":{"totalentreprenad":{"side":"left","heading":"Hela markarbetet hos en entreprenör","text":"Som totalentreprenör tar vi helhetsansvaret – från schaktning och dränering till grundläggning, VA-arbeten och färdig mark. Du får en kontaktperson genom hela projektet.","link":{"label":"Läs mer om totalentreprenad","href":"/tjanster/totalentreprenad"},"image":{"src":"/photos/markmontage-kabeltrumma.webp","variants":[{"width":480,"src":"/photos/markmontage-kabeltrumma-480.webp"},{"width":800,"src":"/photos/markmontage-kabeltrumma-800.webp"},{"width":1200,"src":"/photos/markmontage-kabeltrumma-1200.webp"},{"width":1600,"src":"/photos/markmontage-kabeltrumma-1600.webp"},{"width":2400,"src":"/photos/markmontage-kabeltrumma.webp"}],"alt":"Släp med kabeltrumma vid en avspärrad arbetsplats"}},"bygga":{"side":"right","heading":"Ska du bygga nytt eller bygga till?","text":"Vi tar hand om markarbetet inför bygget – schakt, grundläggning och VA – och samordnar vid behov arbetet med övriga entreprenörer i projektet.","link":{"label":"Begär offert","href":"#offert"},"image":{"src":"/photos/markmontage-minigravare-tradgard.webp","variants":[{"width":480,"src":"/photos/markmontage-minigravare-tradgard-480.webp"},{"width":800,"src":"/photos/markmontage-minigravare-tradgard-800.webp"},{"width":1200,"src":"/photos/markmontage-minigravare-tradgard-1200.webp"},{"width":1600,"src":"/photos/markmontage-minigravare-tradgard-1600.webp"},{"width":1799,"src":"/photos/markmontage-minigravare-tradgard.webp"}],"alt":"Röd minigrävare schaktar i en trädgård intill ett hus"}}}}},"om-oss":{"type":"about","hidden":false,"anchor":"om-oss","label":"","heading":"Om oss","link":{"label":"Mer om oss","href":"/om-oss"},"subheading":"Markmontage BEAB AB har sin bas i Romelanda utanför Kungälv och grundades 2002.","text":"Markmontage BEAB AB är ett entreprenadföretag inom mark- och grundarbeten, verksamt i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd. Vi utför bland annat schaktning, dränering, grundläggning, VA-arbeten och fiberinstallation, har egna kranlastbilar för transporter och lyft, och tar även helhetsansvar som totalentreprenör på större projekt.","image":{"src":"/photos/markmontage-teamet.webp","variants":[{"width":480,"src":"/photos/markmontage-teamet-480.webp"},{"width":800,"src":"/photos/markmontage-teamet-800.webp"},{"width":1200,"src":"/photos/markmontage-teamet-1200.webp"},{"width":1600,"src":"/photos/markmontage-teamet-1600.webp"},{"width":2400,"src":"/photos/markmontage-teamet.webp"}],"alt":"Markmontages medarbetare i overaller samlade vid ett bord utomhus","focus":"50% 40%"}},"process":{"type":"process","hidden":false,"anchor":"process","label":"","heading":"Så går det till","text":"Fyra tydliga steg från första kontakt till avslutat markarbete.","steps":{"order":["kontakt","hembesok","offert","genomforande"],"items":{"kontakt":{"title":"Kontakt","description":"Du hör av dig via telefon eller formuläret och berättar kort om ditt projekt, så återkommer vi snabbt med nästa steg.","icon":"Phone"},"hembesok":{"title":"Kostnadsfritt hembesök","description":"Vi besöker dig på plats för att gå igenom förutsättningarna och lyssna på dina önskemål, helt utan kostnad eller förpliktelser.","icon":"Home"},"offert":{"title":"Fast offert","description":"Du får en tydlig och fast offert innan något arbete påbörjas, så att du vet exakt vad som ingår och vad projektet kostar.","icon":"FileText"},"genomforande":{"title":"Genomförande","description":"Vårt team genomför arbetet enligt tidsplan, med löpande avstämning och fokus på högsta kvalitet hela vägen till ett färdigställt resultat.","icon":"HardHat"}}}},"faq":{"type":"faq","hidden":false,"anchor":"faq","label":"","heading":"Vanliga frågor","phonePrompt":"Hittar du inte svaret? Ring oss på","items":{"order":["offert","tid","totalentreprenor","tjale","rotavdrag","fast-pris","omraden"],"items":{"offert":{"question":"Hur går en offertförfrågan till?","answer":"Du kontaktar oss via telefon eller formuläret på sidan och berättar kort om ditt projekt. Därefter bokar vi ett kostnadsfritt hembesök där vi går igenom förutsättningarna tillsammans, och du får en fast offert innan något arbete påbörjas."},"tid":{"question":"Hur lång tid tar ett mark- eller grundarbete?","answer":"Tidsåtgången beror helt på projektets omfattning – allt från en dränering till grundläggning av en hel villa. Vid hembesöket går vi igenom en realistisk tidsplan för just ditt projekt, så att du vet vad du kan förvänta dig innan arbetet startar."},"totalentreprenor":{"question":"Vad innebär det att ni arbetar som totalentreprenör?","answer":"Som totalentreprenör tar Markmontage BEAB AB helhetsansvaret för mark- och grundarbetet och samordnar samtliga moment som krävs, från schaktning och dränering till grundläggning och VA. Du behöver bara en kontakt genom hela processen istället för att själv hantera flera olika entreprenörer."},"tjale":{"question":"Kan ni arbeta året runt, även när det är tjäle i marken?","answer":"Tjäle påverkar när och hur vissa markarbeten kan utföras. Vid hembesöket bedömer vi förutsättningarna för just din tomt och planerar arbetet efter årstid och väderlek, så att du får en realistisk tidsplan redan från start."},"rotavdrag":{"question":"Kan jag få rotavdrag på mark- och grundarbete?","answer":"Som privatperson kan du få rotavdrag på arbetskostnaden för vissa mark- och grundarbeten vid din bostad, till exempel dränering och grundförstärkning i samband med renovering eller tillbyggnad. Avdraget är 30 procent av arbetskostnaden, upp till 50 000 kronor per person och år. Vi drar av beloppet direkt på fakturan och sköter ansökan till Skatteverket."},"fast-pris":{"question":"Ger ni fast pris på era projekt?","answer":"Ja, efter det kostnadsfria hembesöket får du en fast offert innan arbetet påbörjas, så att du vet exakt vad som ingår och vad projektet kostar. Skulle nya önskemål tillkomma under projektets gång stämmer vi alltid av med dig innan vi går vidare."},"omraden":{"question":"Vilka områden arbetar ni i?","answer":"Vi utför mark- och grundarbeten i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd. Är du osäker på om vi arbetar där du bor är du varmt välkommen att höra av dig, så ger vi dig snabbt besked."}}}},"kontakt":{"type":"contact","hidden":false,"anchor":"kontakt","label":"","heading":"Kontakta oss","text":"Hör av dig för en kostnadsfri offert, så återkommer vi så snart vi kan.","phoneLabel":"Telefon, Jens","emailLabel":"E-post","addressLabel":"Adress","openingHoursLabel":"Öppettider","orgLabel":"Org.nr","formHeading":"Begär offert"},"karta":{"type":"map","hidden":false,"anchor":"","label":"","heading":"Här finns vi","addressPrefix":"Kontor:","linkLabel":"Öppna i Google Maps","zoom":11},"omdomen":{"type":"reviewInvite","hidden":false,"anchor":"omdomen","label":"","badge":"Google-omdöme","heading":"Hur nöjd var du med jobbet?","text":"Har vi gjort ett jobb åt dig? Ditt omdöme hjälper andra att välja rätt entreprenör – och oss att bli ännu bättre.","button":{"label":"Skriv ett omdöme på Google","href":"https://www.google.com/maps/search/?api=1&query=Markmontage%20BEAB%20AB%20Romelanda"}},"kundomdomen":{"type":"testimonials","hidden":false,"label":"","anchor":"kundomdomen","heading":"Vad våra kunder säger","text":"Omdömen från våra kunder på Google.","items":{"order":["omdome-1","omdome-2","omdome-3"],"items":{"omdome-1":{"quote":"Här visas ett omdöme från en kund på Google. Vi lägger in de riktiga omdömena när vi har dem.","name":"Kundens namn","detail":"Omdöme på Google","rating":0,"image":null},"omdome-2":{"quote":"Här visas ett omdöme från en kund på Google. Vi lägger in de riktiga omdömena när vi har dem.","name":"Kundens namn","detail":"Omdöme på Google","rating":0,"image":null},"omdome-3":{"quote":"Här visas ett omdöme från en kund på Google. Vi lägger in de riktiga omdömena när vi har dem.","name":"Kundens namn","detail":"Omdöme på Google","rating":0,"image":null}}}},"certifikat":{"type":"certificateStrip","hidden":false,"label":"","anchor":"","heading":"Certifierade enligt ISO 9001, 14001 och 45001","link":{"label":"Läs om vår hållbarhet","href":"/hallbarhet"}}}}},"om-oss":{"slug":"om-oss","title":"Om oss","seo":{"title":"Om oss","description":"Markmontage BEAB AB utför mark- och grundarbeten i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd sedan 2002."},"sections":{"order":["bild","intro","kontakt","bilder","kranbilar","grunden","jobba"],"items":{"bild":{"type":"pageHero","hidden":false,"anchor":"","label":"","image":{"src":"/photos/markmontage-teamet.webp","variants":[{"width":480,"src":"/photos/markmontage-teamet-480.webp"},{"width":800,"src":"/photos/markmontage-teamet-800.webp"},{"width":1200,"src":"/photos/markmontage-teamet-1200.webp"},{"width":1600,"src":"/photos/markmontage-teamet-1600.webp"},{"width":2400,"src":"/photos/markmontage-teamet.webp"}],"alt":"Markmontages medarbetare samlade vid ett bord utomhus","focus":"50% 35%"},"size":"tall"},"intro":{"type":"aboutIntro","hidden":false,"anchor":"","label":"","heading":"Om oss","subheading":"Markmontage BEAB AB har sin bas i Romelanda utanför Kungälv och grundades 2002.","paragraphs":["Markmontage BEAB AB är ett entreprenadföretag inom mark- och grundarbeten, verksamt i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd. Vi utför bland annat schaktning, dränering, grundläggning, VA-arbeten och fiberinstallation, har egna kranlastbilar för transporter och lyft, och tar även helhetsansvar som totalentreprenör på större projekt.","Markmontage BEAB AB har över 20 års erfarenhet inom branschen. Ett bygge är aldrig starkare än sin grund, och vi lägger därför stor vikt vid fackmannamässigt utförande i varje moment av mark- och grundarbetet.","Markmontage BEAB AB grundades 2002 och har idag 18 anställda.","Du är varmt välkommen att kontakta oss!"],"factsTitle":"Fakta om oss","facts":{"order":["grundat","anstallda","sate","verksamhet","org-nr"],"items":{"grundat":{"label":"Grundat","value":"2002"},"anstallda":{"label":"Anställda","value":"18"},"sate":{"label":"Säte","value":"Romelanda, Kungälv"},"verksamhet":{"label":"Verksamhet","value":"Mark- och grundarbeten"},"org-nr":{"label":"Org.nr","value":"556625-8157"}}}},"bilder":{"type":"photoPair","hidden":false,"anchor":"","label":"","photos":{"order":["bild-1","bild-2"],"items":{"bild-1":{"image":{"src":"/photos/markmontage-konferens.webp","variants":[{"width":480,"src":"/photos/markmontage-konferens-480.webp"},{"width":800,"src":"/photos/markmontage-konferens-800.webp"},{"width":1200,"src":"/photos/markmontage-konferens-1200.webp"},{"width":1600,"src":"/photos/markmontage-konferens-1600.webp"},{"width":2400,"src":"/photos/markmontage-konferens.webp"}],"alt":"Medarbetare på konferens i en lokal med storbildsskärm","focus":"50% 50%"}},"bild-2":{"image":{"src":"/photos/markmontage-kran-flagga.webp","variants":[{"width":480,"src":"/photos/markmontage-kran-flagga-480.webp"},{"width":800,"src":"/photos/markmontage-kran-flagga-800.webp"},{"width":1200,"src":"/photos/markmontage-kran-flagga-1200.webp"},{"width":1600,"src":"/photos/markmontage-kran-flagga-1600.webp"},{"width":1800,"src":"/photos/markmontage-kran-flagga.webp"}],"alt":"Kranbil med utfälld kran och en grävmaskin vid Markmontages kontor","focus":"50% 45%"}}}}},"grunden":{"type":"band","hidden":false,"anchor":"","label":"","heading":"Vi lägger grunden för ditt bygge","text":"Vi utför bland annat schaktning, dränering, grundläggning, VA-arbeten, fiberinstallation och transporter med kranbil i Kungälv, Stenungsund, Ale, Trestad och Göteborg med omnejd – och tar helhetsansvar som totalentreprenör på större projekt. Oavsett uppdrag lägger vi stor vikt vid fackmannamässigt utförande i varje moment.","link":{"label":"Se våra tjänster","href":"/#tjanster"},"image":{"src":"/photos/markmontage-gravmaskin-ror.webp","variants":[{"width":480,"src":"/photos/markmontage-gravmaskin-ror-480.webp"},{"width":800,"src":"/photos/markmontage-gravmaskin-ror-800.webp"},{"width":1200,"src":"/photos/markmontage-gravmaskin-ror-1200.webp"},{"width":1600,"src":"/photos/markmontage-gravmaskin-ror-1600.webp"},{"width":2400,"src":"/photos/markmontage-gravmaskin-ror-2400.webp"},{"width":3840,"src":"/photos/markmontage-gravmaskin-ror.webp"}],"alt":"Grävmaskin och medarbetare i varselkläder vid en schakt"},"secondHeading":"Från första spadtaget till färdig yta","secondText":"Du hör av dig, vi kommer ut på ett kostnadsfritt hembesök och du får en fast offert innan något arbete påbörjas. Därefter genomför vi arbetet enligt tidsplan, med löpande avstämning hela vägen.","secondLink":{"label":"Begär offert","href":"#offert"}},"kontakt":{"type":"team","hidden":false,"label":"","anchor":"kontaktpersoner","heading":"Kontakta oss direkt","text":"","members":{"order":["jens","alice"],"items":{"jens":{"name":"Jens Svensson","role":"VD","phone":"070-434 40 56","email":"jens@markmontage.se","image":null},"alice":{"name":"Alice","role":"","phone":"","email":"alice@markmontage.se","image":null}}}},"kranbilar":{"type":"pricelist","hidden":false,"label":"","anchor":"kranbilar","heading":"Våra kranbilar","text":"Med egna kranlastbilar kan vi både frakta och lyfta på plats.","rows":{"order":["scania","volvo"],"items":{"scania":{"name":"Scania med Palfinger-kran","description":"Vår orange kranlastbil med lång kran för lyft på stort avstånd, till exempel maskiner, pooler och byggmaterial.","price":"Uppgift kommer"},"volvo":{"name":"Volvo FMX med Palfinger PK 27002-SH","description":"Kranbil med personkorg för arbete på höjd, till exempel vid fasader, stolpar och ledningar.","price":"Uppgift kommer"}}},"note":"Lyftkapacitet och räckvidd fyller vi i inom kort."},"jobba":{"type":"text","hidden":false,"label":"","anchor":"jobba","heading":"Jobba hos oss","paragraphs":["Vi är ett 18-tal medarbetare som arbetar med mark, kabel och fundament runt Kungälv och Göteborg. Hos oss jobbar du med maskiner och kranbilar i varierande uppdrag, i ett team där vi hjälps åt.","Är du intresserad av att jobba hos oss? Skicka några rader om dig själv, så hör vi av oss när vi söker folk."],"image":{"src":"/photos/markmontage-teamet.webp","variants":[{"width":480,"src":"/photos/markmontage-teamet-480.webp"},{"width":800,"src":"/photos/markmontage-teamet-800.webp"},{"width":1200,"src":"/photos/markmontage-teamet-1200.webp"},{"width":1600,"src":"/photos/markmontage-teamet-1600.webp"},{"width":2400,"