utning-800.webp"},{"width":1200,"src":"/photos/markmontage-pool-gjutning-1200.webp"},{"width":1600,"src":"/photos/markmontage-pool-gjutning-1600.webp"},{"width":2016,"src":"/photos/markmontage-pool-gjutning.webp"}],"alt":"Betongbil gjuter en pool i en villaträdgård","focus":"50% 50%"}}}}},"referens-glasfiberpool":{"type":"reference","hidden":false,"anchor":"glasfiberpool","label":"","badge":"Referens","heading":"Glasfiberpool i trädgård","text":"","steps":{"order":["utmaning","losning","resultat"],"items":{"utmaning":{"label":"Utmaningen","heading":"En färdig pool ner i trädgården","text":"En glasfiberpool kommer i ett stycke. Den behöver en plan och stabil bädd, och ett lyft ner i gropen.","image":{"src":"/photos/markmontage-pool-makadam.webp","variants":[{"width":480,"src":"/photos/markmontage-pool-makadam-480.webp"},{"width":800,"src":"/photos/markmontage-pool-makadam-800.webp"},{"width":1200,"src":"/photos/markmontage-pool-makadam-1200.webp"},{"width":1600,"src":"/photos/markmontage-pool-makadam-1600.webp"},{"width":1800,"src":"/photos/markmontage-pool-makadam.webp"}],"alt":"Schaktad grop med makadambädd inför en pool","focus":"50% 50%"}},"losning":{"label":"Lösningen","heading":"Makadambädd och kranlyft","text":"Vi schaktade gropen, lade en bädd av makadam och lyfte poolen på plats med kran.","image":{"src":"/photos/markmontage-pool-lyft.webp","variants":[{"width":480,"src":"/photos/markmontage-pool-lyft-480.webp"},{"width":800,"src":"/photos/markmontage-pool-lyft-800.webp"},{"width":960,"src":"/photos/markmontage-pool-lyft.webp"}],"alt":"En pool lyfts med kran ner i en trädgård","focus":"50% 55%"}},"resultat":{"label":"Resultatet","heading":"Poolen på plats","text":"Poolen står på plats med rören dragna, redo att fyllas runt om.","image":{"src":"/photos/markmontage-pool-glasfiber.webp","variants":[{"width":480,"src":"/photos/markmontage-pool-glasfiber-480.webp"},{"width":800,"src":"/photos/markmontage-pool-glasfiber-800.webp"},{"width":1200,"src":"/photos/markmontage-pool-glasfiber-1200.webp"},{"width":1600,"src":"/photos/markmontage-pool-glasfiber-1600.webp"},{"width":1800,"src":"/photos/markmontage-pool-glasfiber.webp"}],"alt":"En glasfiberpool på plats i en schaktad grop i en trädgård","focus":"50% 45%"}}}}},"referens-fiber":{"type":"reference","hidden":false,"anchor":"fiber-sjo","label":"","badge":"Referens","heading":"Kabelförläggning i sjö","text":"","steps":{"order":["utmaning","losning"],"items":{"utmaning":{"label":"Utmaningen","heading":"Fiber över vatten","text":"Fiberkabeln skulle dras över en sjö, där det inte går att schakta som på land.","image":{"src":"/photos/markmontage-fiber-bat.webp","variants":[{"width":480,"src":"/photos/markmontage-fiber-bat-480.webp"},{"width":800,"src":"/photos/markmontage-fiber-bat-800.webp"},{"width":1125,"src":"/photos/markmontage-fiber-bat.webp"}],"alt":"Båt bogserar pråmen vid kabelförläggning i sjö","focus":"50% 45%"}},"losning":{"label":"Lösningen","heading":"Pråm, båt och kabeltrumma","text":"Kabeltrumman stod på en pråm som båten bogserade, och kabeln lades ut längs hela sträckan.","image":{"src":"/photos/markmontage-fiber-kabeltrumma.webp","variants":[{"width":480,"src":"/photos/markmontage-fiber-kabeltrumma-480.webp"},{"width":800,"src":"/photos/markmontage-fiber-kabeltrumma-800.webp"},{"width":1125,"src":"/photos/markmontage-fiber-kabeltrumma.webp"}],"alt":"Kabeltrumma på pråm vid kabelförläggning i sjö","focus":"50% 45%"}}}}}}}},"hallbarhet":{"slug":"hallbarhet","title":"Hållbarhet","seo":{"title":"Hållbarhet – certifikat och policyer","description":"Markmontage BEAB AB är certifierat enligt ISO 9001, ISO 14001 och ISO 45001. Här finns våra certifikat och våra policyer för kvalitet, miljö och arbetsmiljö."},"sections":{"order":["bild","certifikat","policyer","offert"],"items":{"bild":{"type":"pageHero","hidden":false,"anchor":"","label":"","image":{"src":"/photos/markmontage-arbete.webp","variants":[{"width":480,"src":"/photos/markmontage-arbete-480.webp"},{"width":800,"src":"/photos/markmontage-arbete-800.webp"},{"width":1200,"src":"/photos/markmontage-arbete-1200.webp"},{"width":1600,"src":"/photos/markmontage-arbete-1600.webp"},{"width":2400,"src":"/photos/markmontage-arbete.webp"}],"alt":"Medarbetare vid avspärrningen på en arbetsplats med servicebilar"},"size":"medium"},"certifikat":{"type":"certificates","hidden":false,"anchor":"","label":"","heading":"Hållbarhet","text":"Kvalitet, miljö och arbetsmiljö är en del av hur vi arbetar varje dag. Markmontage är certifierat enligt ISO 9001, ISO 14001 och ISO 45001 – de internationella standarderna för kvalitet, miljö och arbetsmiljö – utfärdade av Svensk Certifiering. Dessutom har vi kreditbetyget AA från Dun & Bradstreet. Längre ner finns våra policyer.","issuerPrefix":"Utfärdat av","validUntilPrefix":"Giltigt till","documentLabel":"Se hela certifikatet (PDF)","emptyHeading":"Certifikaten läggs upp inom kort","emptyText":"Har du frågor om våra certifikat och behörigheter är du välkommen att ringa oss på"},"offert":{"type":"cta","hidden":false,"anchor":"","label":"","heading":"Har du ett markprojekt på gång?","text":"Berätta kort om ditt projekt, så återkommer vi med nästa steg.","button":{"label":"Begär offert","href":"#offert"}},"policyer":{"type":"policies","hidden":false,"anchor":"policyer","label":"","heading":"Våra policyer","text":"Policyerna beskriver hur vi arbetar med kvalitet, miljö och arbetsmiljö, och vilka mål vi följer upp.","goalLabel":"Mål","measureLabel":"Uppföljning:","documentLabel":"Läs hela policyn (PDF)","items":{"order":["kvalitet","miljo","arbetsmiljo"],"items":{"kvalitet":{"name":"Kvalitetspolicy","icon":"BadgeCheck","paragraphs":["Markmontage ska arbeta för att ständigt förbättra och utveckla sin verksamhet. Vi är innovativa i all vår företagsamhet, viljan att alltid utveckla och förbättra vår verksamhet skall vara påtaglig. Vi uppfyller de lagar och krav som ställs på oss.","Vi strävar efter att ständigt förbättra vårt verksamhetssystem så att vårt arbete därigenom kan bedrivas på ett mera effektivt sätt.","Vi uppfyller våra kunders krav på kvalitet avseende de tjänster och produkter som vi tillhandahåller."],"goals":{"order":["forbattringsforslag"],"items":{"forbattringsforslag":{"goal":"Antal förbättringsförslag, därav även delaktigheten av företagets kvalitet, från medarbetare och andra intressenter skall öka med 50 % årligen.","measure":"Uppföljning och genomförande av förbättringsförslagen."}}},"document":"/dokument/markmontage-kvalitetspolicy.pdf"},"miljo":{"name":"Miljöpolicy","icon":"Leaf","paragraphs":["Markmontage tar ansvar för vår miljöpåverkan, genom kunskap, kompetens och engagemang bidra till en hållbar miljö. Ambitionen är att minska koncernens klimatpåverkan genom hela projekten. Vi jobbar ständigt med vårt miljöarbete och ser till att det bedrivs systematiskt med en tydlig struktur.","Vi strävar efter att använda miljömärkta produkter, i den mån de finns tillgängliga på marknaden samt uppfyller våra egna krav på egenskaper och ekonomi."],"goals":{"order":["fordon"],"items":{"fordon":{"goal":"För att minska klimatpåverkan och främja en mer hållbar verksamhet ska befintlig maskin- och fordonspark som drivs av fossila bränslen fasas ut enligt fastställd planering. Ersättning ska ske med fordon och maskiner som uppfyller miljöklass Euro 6 eller bättre.","measure":"Företagets fordonsinnehavslista samt företagets utfasningsplanering för fordon."}}},"document":"/dokument/markmontage-miljopolicy.pdf"},"arbetsmiljo":{"name":"Arbetsmiljöpolicy","icon":"HardHat","paragraphs":["Markmontage bedriver ett systematiskt arbetsmiljöarbete som integreras i de övriga verksamhetsfrågorna. Våra medarbetare är vår viktigaste resurs. Genom att integrera hälsa och säkerhet i vårt dagliga arbete skapar vi en god och säker fysisk, psykisk och social sund och utvecklande arbetsplats för alla medarbetare.","Vi bedriver ett långsiktigt och strategiskt arbete för att främja jämställdhet samt stärka den organisatoriska och sociala arbetsmiljön inom verksamheten. Arbetet utgår från ett förbättringsperspektiv och genomsyras i ledarskapet.","Vi har absolut nolltolerans för hot och våld samt kränkande särbehandling och uppmuntrar till att vi anmäler om vi misstänker att detta pågår i vår organisation."],"goals":{"order":["utbildning","upplevelse"],"items":{"utbildning":{"goal":"100 % av vår personal skall ha fått internutbildning i arbetsmiljön på Markmontage och inneha rätt kompetens inom arbetsmiljö.","measure":"Uppföljning av kompetensmatrisen."},"upplevelse":{"goal":"90 % av medarbetarna ger minst 6 i positiv uppskattning på en 10-gradig skala i hur deras arbetsmiljö upplevs generellt på Markmontage.","measure":"Resultatet från medarbetarsamtalen, där medarbetarna berättar hur de upplever arbetsmiljön generellt på Markmontage."}}},"document":"/dokument/markmontage-arbetsmiljopolicy.pdf"}}}}}}}}}}$baseline$::jsonb)
on conflict (id) do nothing;

insert into public.content_revisions (version, snapshot, source, summary)
select 1, data, 'baseline', 'Ursprunglig version' from public.site_snapshot
where id = 1 and not exists (select 1 from public.content_revisions where source = 'baseline');

select private.set_theme_tables(data -> 'theme') from public.site_snapshot where id = 1;

insert into public.website_colors (scope, key, value) values ('admin', 'primary', '#1C2817')
on conflict (scope, key) do nothing;

insert into private.admin_allowlist (email) values ('info@markmontage.se') on conflict do nothing;

insert into public.credit_balance (account_id, balance) values ('site', 100) on conflict (account_id) do nothing;
insert into public.credit_transactions (amount, type, description, balance_after)
select 100, 'grant', 'Startkredit som ingår i abonnemanget', 100
where not exists (select 1 from public.credit_transactions);

-- The packs offered under "Fyll på credits". Prices are set by Elevate Studio (null: shown as per agreement).
insert into public.settings (key, value) values
  ('credit_packs', '[{"credits": 50, "price": null}, {"credits": 100, "price": null}, {"credits": 250, "price": null}, {"credits": 500, "price": null}]'),
  ('onboarding', '{"done": [], "dismissed": false}'),
  ('deploy', '{"status": "idle"}')
on conflict (key) do nothing;
